parameters.jsCode:
const leads = $input.all().map(item => item.json);

const byStage = {};
const byOwner = {};
let newLeadsCount = 0;
let totalScore = 0;
let scoredLeads = 0;

for (const lead of leads) {
  const stage = lead.Lead_Status || 'No Status';
  byStage[stage] = (byStage[stage] || 0) + 1;

  const owner = lead.Owner?.name || 'No Owner';
  byOwner[owner] = (byOwner[owner] || 0) + 1;

  if ((lead.Lead_Status || '').toLowerCase() === 'new') {
    newLeadsCount++;
  }

  if (lead.AI_score && lead.AI_score > 0) {
    totalScore += lead.AI_score;
    scoredLeads++;
  }
}

const avgScore = scoredLeads > 0 ? Math.round(totalScore / scoredLeads) : 0;

return [{
  json: {
    total_leads: leads.length,
    new_leads_count: newLeadsCount,
    avg_ai_score: avgScore,
    by_stage: JSON.stringify(byStage),
    by_owner: JSON.stringify(byOwner)
  }
}];

